-- Club 1 (CSS Sfax) athletes 1,3 linked to Khaled Mzoughi and Amine Chaabani
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'khaled.mzoughi@ftn.tn')
WHERE id = 1;
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'amine.chaabani@ftn.tn')
WHERE id = 3;

-- Club 2 (EST) athletes 4,5,6 linked to Sarra, Yassine, Rim
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'sarra.belhadj@ftn.tn')
WHERE id = 4;
