WHERE id = 6;

-- Club 3 (CA) athlete 7 linked to Maher Slimani
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'maher.slimani@ftn.tn')
WHERE id = 7;

-- Club 5 (Monastir) athlete 13 linked to Nadia Trabelsi
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'nadia.trabelsi@ftn.tn')
WHERE id = 13;

-- Club 6 (Sousse) athlete 17 linked to Olfa Bouzid
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'olfa.bouzid@ftn.tn')
WHERE id = 17;

-- Club 2 (EST) extra athlete 28 linked to Tarek Ayari
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'tarek.ayari@ftn.tn')
WHERE id = 28;

-- Club 3 (CA) extra athlete 31 linked to Intissar Khelifi
UPDATE athletes SET user_id = (SELECT id FROM users WHERE email = 'intissar.khelifi@ftn.tn')
WHERE id = 31;

